class Registrar:
    def __init__(self):
        self.courses = {}
        self.students = {}
        self.enrollments = {}

    def add_course(self, course_id: str, capacity: int) -> None:
        if not course_id:
            raise ValueError("Course ID cannot be empty")
        if not isinstance(capacity, int) or capacity <= 0:
            raise ValueError("Capacity must be a positive integer")
        if course_id in self.courses:
            raise EnrollmentError(f"Course '{course_id}' already exists")
        self.courses[course_id] = {'capacity': capacity, 'roster': []}

    def add_student(self, student_id: str) -> None:
        if not student_id:
            raise ValueError("Student ID cannot be empty")
        if student_id in self.students:
            raise EnrollmentError(f"Student '{student_id}' already exists")
        self.students[student_id] = {'schedule': []}

    def enroll(self, student_id: str, course_id: str) -> None:
        if student_id not in self.students or course_id not in self.courses:
            raise KeyError(f"Student '{student_id}' or course '{course_id}' not found")
        if student_id in self.enrollments.get(course_id, []):
            raise EnrollmentError(f"Student '{student_id}' is already enrolled in course '{course_id}'")
        if len(self.courses[course_id]['roster']) >= self.courses[course_id]['capacity']:
            raise CourseFull(f"Course '{course_id}' is full")
        self.enrollments.setdefault(course_id, []).append(student_id)
        self.students[student_id]['schedule'].append(course_id)
        self.courses[course_id]['roster'].append(student_id)

    def get_roster(self, course_id: str) -> list[str]:
        if course_id not in self.courses:
            raise KeyError(f"Course '{course_id}' not found")
        return self.courses[course_id]['roster']

    def get_schedule(self, student_id: str) -> list[str]:
        if student_id not in self.students:
            raise KeyError(f"Student '{student_id}' not found")
        return self.students[student_id]['schedule']

    def get_open_seats(self, course_id: str) -> int:
        if course_id not in self.courses:
            raise KeyError(f"Course '{course_id}' not found")
        return self.courses[course_id]['capacity'] - len(self.courses[course_id]['roster'])
