            raise KeyError("Book not found in catalog")

        if self.books[isbn]['copies'] == 0:
            raise NoCopyAvailable("No copies available")

        self.books[isbn]['copies'] -= 1
        self.books[isbn]['loans'].append(borrower)
        self.books[isbn]['history'].append(('check_out', borrower))

    def return_book(self, isbn: str, borrower: str) -> None:
        if not borrower:
            raise ValueError("Borrower ID cannot be empty")

        if isbn not in self.books:
            raise KeyError("Book not found in catalog")

        if borrower not in self.books[isbn]['loans']:
            raise LibraryError("Borrower does not have this book checked out")

        self.books[isbn]['copies'] += 1
        self.books[isbn]['loans'].remove(borrower)
        self.books[isbn]['history'].append(('return', borrower))

    def get_available(self, isbn: str) -> int:
        if isbn not in self.books:
            raise KeyError("Book not found in catalog")

        return self.books[isbn]['copies']

    def get_loans(self, borrower: str) -> list[str]:
