    def __init__(self):
        self.levels = {}
        self.vehicles = {}

    def add_level(self, level_id: str, spots: int) -> None:
        if not level_id or not isinstance(level_id, str):
            raise ValueError("Invalid level id")
        if not isinstance(spots, int) or spots <= 0:
            raise ValueError("Invalid spot count")
        if level_id in self.levels:
            raise GarageError("Level already exists")
        self.levels[level_id] = {'spots': spots, 'free_spots': spots, 'vehicles': []}

    def enter(self, plate: str, minute: int) -> str:
        if not plate or not isinstance(plate, str):
            raise ValueError("Invalid plate")
        if not isinstance(minute, int) or minute < 0:
            raise ValueError("Invalid minute")
        if plate in self.vehicles:
            raise GarageError("Vehicle already parked")
        for level_id, level in self.levels.items():
            if level['free_spots'] > 0:
                level['vehicles'].append(plate)
                level['free_spots'] -= 1
                self.vehicles[plate] = {'level_id': level_id, 'minute': minute}
                return level_id
        raise GarageFull("Garage is full")

    def leave(self, plate: str, minute: int) -> int:
        if plate not in self.vehicles:
            raise KeyError("Vehicle not found")
        if not isinstance(minute, int) or minute < self.vehicles[plate]['minute']:
            raise ValueError("Invalid minute")
        level_id = self.vehicles[plate]['level_id']
        entry_minute = self.vehicles[plate]['minute']
        self.vehicles.pop(plate)
        self.levels[level_id]['vehicles'].remove(plate)
        self.levels[level_id]['free_spots'] += 1
        return minute - entry_minute

    def get_level(self, plate: str) -> str:
        if plate not in self.vehicles:
            raise KeyError("Vehicle not found")
        return self.vehicles[plate]['level_id']

    def get_free_spots(self, level_id: str) -> int:
