        self.player_dict[name] = {"name": name, "position": position, "salary": salary}

    def remove_player(self, name: str) -> None:
        if name not in self.player_dict:
            raise KeyError(f"Player {name} not found")
        self.players.remove(name)
        del self.player_dict[name]

    def get_players(self, position: str | None = None) -> list[str]:
        if position is not None and position not in POSITIONS:
            raise ValueError(f"Invalid position: {position}")
        if position:
            return [player for player in self.players if self.player_dict[player]["position"] == position]
        return self.players

    def get_player(self, name: str) -> dict:
        if name not in self.player_dict:
            raise KeyError(f"Player {name} not found")
        return self.player_dict[name]

    def get_payroll(self) -> int:
        return sum(player["salary"] for player in self.player_dict.values())

    def get_cap_space(self) -> int:
