    def get_players(self, position: Optional[str] = None) -> List[str]:
        if position is not None and position not in POSITIONS:
            raise ValueError(f"Invalid position: {position}")
        return [player for player in self.player_order if position is None or self.players[player]["position"] == position]

    def get_player(self, name: str) -> Dict[str, int]:
        if name not in self.players:
            raise KeyError(f"Player {name} not found")
        return self.players[name]

    def get_payroll(self) -> int:
        return sum(player["salary"] for player in self.players.values())

    def get_cap_space(self) -> int:
        return self.salary_cap - self.get_payroll()
